gBwText_80_0:
	.string "Current winning streak: {STR_VAR_1}!\pNext car: No. {STR_VAR_2}.\nContinue to battle?$"
gBwText_80_1:
	.string "CONTINUE$"
gBwText_80_2:
	.string "RECORD$"
gBwText_80_3:
	.string "REST$"
gBwText_80_4:
	.string "RETIRE$"
gBwText_80_5:
	.string "Cancel your challenge?$"
gBwText_80_6:
	.string "Save and quit the game?$"
gBwText_80_7:
	.string "Saving...\nDon't turn off the power.$"
gBwText_80_8:
	.string "Delete your existing Battle Video and\nsave the last battle?$"
gBwText_80_9:
	.string "Awaiting your friend's selection.$"
gBwText_80_10:
	.string "$"
gBwText_80_11:
	.string "You have chosen to retire from\nthis challenge.$"
gBwText_80_12:
	.string "Saving your Battle Video...\nDon't turn off the power.$"
gBwText_80_13:
	.string "{STR_VAR_1}'s battle has been saved as\na Battle Video.$"
gBwText_80_14:
	.string "Would you like to save the last battle\nas your Battle Video?$"
gBwText_80_15:
	.string "Communicating. Please stand by...$"
gBwText_80_16:
	.string "$"
