	.4byte 4
gBwText_268_0:
	.string "$"
gBwText_268_1:
	.string "$"
gBwText_268_2:
	.string "$"
gBwText_268_3:
	.string "$"
gBwText_268_4:
	.string "$"
gBwText_268_5:
	.string "$"
gBwText_268_6:
	.string "$"
gBwText_268_7:
	.string "Hello! If you cross the Skyarrow Bridge\nfrom this side, you will reach\lPinwheel Forest and Nacrene City.$"
gBwText_268_8:
	.string "I walked so far! My legs are sore!\n...Um, you don't have to look.$"
	.align 2
	.global gBwTextTable_268
