gBwTextCount_272:
	.4byte 3
gBwText_273_0:
	.string "I'm totally hooked on Village\nSandwiches!\pWe moved closer to the shop so I could\neat there every day.$"
gBwText_273_1:
	.string "This is a very old bridge, but thanks to\nthe elderly man next door who takes\lcare of it, the bridge always looks its\lbest!$"
gBwText_273_2:
	.string "Village Bridge is the oldest bridge in\nUnova. It says so right here in my book!\pI heard it was built 200 years ago!$"
	.align 2
	.global gBwTextTable_273
