gBwTextCount_276:
	.4byte 8
gBwText_277_0:
	.string "Both you and your Pokémon are healthy\nand energetic!\pIf you get tired, please talk to me.\nI'll let you take a nice long rest.$"
gBwText_277_1:
	.string "Oh, your Pokémon look pretty tired.\nDon't be shy. Take a nice long rest!$"
	.align 2
	.global gBwTextTable_277
