	.string "{STR_VAR_1} obtained {STR_VAR_2}!$"
gBwText_283_1:
	.string "{STR_VAR_1} obtained the {STR_VAR_2}!$"
gBwText_283_2:
	.string "$"
gBwText_283_3:
	.string "{STR_VAR_1} obtained\n{STR_VAR_2} {STR_VAR_3}!$"
gBwText_283_4:
	.string "{STR_VAR_1} found {STR_VAR_2}!$"
gBwText_283_5:
	.string "{STR_VAR_1} found {STR_VAR_2}!$"
gBwText_283_6:
	.string "{STR_VAR_1} found\n{STR_VAR_2} {STR_VAR_3}!$"
gBwText_283_7:
	.string "Too bad! There is no more room for\n{STR_VAR_1}!$"
gBwText_283_8:
	.string "Too bad! There is no more room for\n{STR_VAR_1}!$"
gBwText_283_9:
	.string "$"
gBwText_283_10:
	.string "{STR_VAR_1} put the {STR_VAR_2} in the\n{STR_VAR_3} Case.$"
gBwText_283_11:
	.string "{STR_VAR_1} put the {STR_VAR_2} in the\n{STR_VAR_3} Case.$"
gBwText_283_12:
	.string "$"
gBwText_283_13:
	.string "You find a note on the item.\p“Please make good use of this item on\nyour adventure! Sincerely, {STR_VAR_3}“\pIt looks like {STR_VAR_3} hid the item.$"
gBwText_283_14:
	.string "Too bad! The Bag is full!\n{STR_VAR_1} gave up the hidden item.$"
