gBwText_410_0:
	.string "Route 15$"
gBwText_410_1:
	.string "Route 15$"
gBwText_410_2:
	.string "Poké Transfer Lab\nWhat's Poké Transfer? Come find out!$"
gBwText_410_3:
	.string "Marvelous Bridge\nTruly marvelous! And also a bridge!$"
	.align 2
	.global gBwTextTable_410
