gBwText_424_0:
	.string "Welcome!\nMay I help you?$"
gBwText_424_1:
	.string "Welcome to the Technical Machine\ndepartment! May I help you?$"
gBwText_424_2:
	.string "Is there anything else I may do\nfor you?$"
gBwText_424_3:
	.string "Please come again!$"
gBwText_424_4:
	.string "Hello!$"
gBwText_424_5:
	.string "Buy$"
gBwText_424_6:
	.string "Sell$"
gBwText_424_7:
	.string "No thanks!$"
gBwText_424_8:
	.string "Welcome to the\nExchange Service Corner!\pWould you like to trade in your BP\nfor some fabulous prizes?$"
gBwText_424_9:
	.string "Please save some BP\nand come see us again.$"
	.align 2
