gBwTextCount_442:
	.4byte 3
gBwText_443_0:
	.string "This is a Poké Ball I got in the past.\nI'm going to give it to you.$"
gBwText_443_1:
	.string "You can't catch a Pokémon\nif you don't have a Poké Ball!\pThere are many types of Poké Balls,\nso use the best one for the job.$"
gBwText_443_2:
	.string "Skree skree!$"
gBwText_443_3:
	.string "Hi, hi! Let's play Pokémon\nrock-paper-scissors!$"
gBwText_443_4:
	.string "Oh, that's no fun!$"
gBwText_443_5:
	.string "Here goes!\nPokémon rock-paper-scissors...$"
gBwText_443_6:
	.string "Your Pokémon is Fire type,\nand mine is Grass type...\pGrass type is weak against Fire type...\nso I lose.$"
gBwText_443_7:
	.string "Your Pokémon is Fire type,\nand mine is Water type...\pFire type is weak against Water type...\nso I win!$"
gBwText_443_8:
	.string "Your Pokémon is Water type,\nand mine is Fire type...\pFire type is weak against Water type...\nso I lose.$"
gBwText_443_9:
	.string "Your Pokémon is Water type,\nand mine is Grass type...\pWater type is weak against Grass type...\nso I win!$"
gBwText_443_10:
	.string "Your Pokémon is Grass type,\nand mine is Water type...\pWater type is weak against Grass type...\nso I lose.$"
gBwText_443_11:
	.string "Your Pokémon is Grass type,\nand mine is Fire type...\pGrass type is weak against Fire type...\nso I win!$"
gBwText_443_12:
	.string "FIRE$"
gBwText_443_13:
	.string "GRASS$"
gBwText_443_14:
	.string "WATER$"
	.align 2
	.global gBwTextTable_443
